'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import { PRODUCT_PAGE_SIZE, type ListingLifecycleAction, type ProductListQuery, type ProductStatus, type VendorProduct, vendorCatalogService } from '@/lib/vendor/catalog'
import { CatalogEmptyState } from '../components/CatalogEmptyState'
import { CatalogFeedback } from '../components/CatalogFeedback'
import { ConfirmModal } from '../components/ConfirmModal'
import { ProductSearchBar } from '../components/ProductSearchBar'
import { ProductTable } from '../components/ProductTable'

export default function VendorProductsPage() {
  const [vendorId, setVendorId] = useState<string | null>(null); const [result, setResult] = useState<Awaited<ReturnType<typeof vendorCatalogService.list>> | null>(null); const [query, setQuery] = useState<ProductListQuery>({ status: 'all', sort: 'updated_desc', page: 1, pageSize: PRODUCT_PAGE_SIZE }); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [confirmation, setConfirmation] = useState<{ product: VendorProduct; status?: ProductStatus; lifecycleAction?: ListingLifecycleAction } | null>(null)
  useEffect(() => { const supabase = createClient(); void supabase.auth.getUser().then(({ data: { user } }) => { if (user && (getUserRole(user) === 'vendor' || getUserRole(user) === 'admin')) setVendorId(user.id); else setLoading(false) }) }, [])
  useEffect(() => { if (!vendorId) return; const currentVendorId = vendorId; async function loadCatalog() { setLoading(true); try { setResult(await vendorCatalogService.list(currentVendorId, query)); setError('') } catch { setError('We could not load your catalog.') } finally { setLoading(false) } } void loadCatalog() }, [vendorId, query])
  function changeStatus(product: VendorProduct, status: ProductStatus) { setConfirmation({ product, status }) }
  function changeLifecycle(product: VendorProduct, lifecycleAction: ListingLifecycleAction) { setConfirmation({ product, lifecycleAction }) }
  async function confirmChange() { if (!vendorId || !confirmation) return; const currentVendorId = vendorId; try { if (confirmation.status) await vendorCatalogService.changeStatus(currentVendorId, confirmation.product.id, confirmation.status); else if (confirmation.lifecycleAction) await vendorCatalogService.performLifecycleAction(currentVendorId, confirmation.product.id, confirmation.lifecycleAction); setConfirmation(null); setResult(await vendorCatalogService.list(currentVendorId, query)) } catch { setError('This status change could not be completed.') } }
  const lifecycleCopy: Record<ListingLifecycleAction, { title: string; message: string }> = { activate: { title: 'Activate this listing?', message: 'Customers will be able to see and purchase this approved listing.' }, deactivate: { title: 'Deactivate this listing?', message: 'The listing will remain preserved but will no longer be visible as active. You can reactivate it later.' }, discontinue: { title: 'Discontinue this product?', message: 'The product will remain preserved for history but will no longer be treated as an active listing.' }, archive: { title: 'Archive this listing?', message: 'The listing will be removed from active work without deleting its historical record.' }, request_removal: { title: 'Request permanent removal?', message: 'The marketplace team must approve removal. The record will remain preserved meanwhile.' }, restore: { title: 'Restore this listing?', message: 'The listing will return as inactive and can be activated again later.' } }
  const confirmationCopy = confirmation?.lifecycleAction ? lifecycleCopy[confirmation.lifecycleAction] : { title: 'Submit this product?', message: 'The product will enter the approval workflow and may be locked while under review.' }
  return <main className="vendor-page"><header className="vendor-header"><Link href="/vendor" className="logo logo-active">Furnish<span>AI</span></Link><nav><Link href="/vendor" className="btn-skip">Onboarding</Link><Link href="/vendor/imports" className="btn-skip">Bulk import</Link><span className="vendor-header-label">Catalog</span></nav></header><div className="catalog-page-shell"><div className="catalog-page-heading"><div><p className="vendor-eyebrow">Vendor portal / Phase 02</p><h1>Product catalog</h1><p>Keep your listings accurate, review-ready, and easy to manage.</p></div><div className="catalog-heading-actions"><Link href="/vendor/imports" className="btn-skip">Bulk import</Link><Link href="/vendor/products/new" className="btn-next">Add product</Link></div></div><ProductSearchBar query={query} onChange={setQuery} />{error ? <CatalogFeedback type="error">{error}</CatalogFeedback> : null}{loading ? <CatalogFeedback type="loading">Loading your catalog...</CatalogFeedback> : result?.items.length ? <ProductTable result={result} onStatusChange={changeStatus} onLifecycleAction={changeLifecycle} onPageChange={(page) => setQuery((current) => ({ ...current, page }))} /> : <CatalogEmptyState filtered={Boolean(query.search || query.status !== 'all' || query.category !== 'all')} />}</div>{confirmation ? <ConfirmModal title={confirmationCopy.title} message={confirmationCopy.message} confirmLabel="Confirm change" onConfirm={() => void confirmChange()} onCancel={() => setConfirmation(null)} /> : null}</main>
}